{
  "name": "Luminos精密滚转轴",
  "name_en": "Luminos Precision Roll Axis",
  "manufacturer": "Zaber Technologies",
  "description": "这是一种电动精密滚转旋转轴，通常集成在多轴定位或光学对准平台中，用于让样品、光纤夹具或光学元件绕滚转轴进行微小角度调整。它常用于光子器件耦合、显微与光学实验中的精密姿态校准和重复定位。",
  "description_en": "This is a motorized precision roll axis typically integrated into a multi-axis positioning or optical alignment stage. It is used to rotate a sample, fiber fixture, or optical component about the roll axis with fine angular control. It is commonly used for photonic device coupling, microscopy, and precision attitude alignment in optical experiments.",
  "tag_hints": [
    "optical alignment",
    "precision rotation stage",
    "roll axis control",
    "multi-axis positioning",
    "photonics coupling",
    "motorized stage",
    "angular positioning"
  ],
  "actions": [
    {
      "action_name": "auto-arc_second_per_step",
      "description": "获取每电机步对应的角秒数。",
      "description_en": "Get the number of arcseconds per motor step."
    },
    {
      "action_name": "auto-home",
      "description": "执行回零，使滚转轴返回参考原点位置。",
      "description_en": "Home the roll axis to its reference position."
    },
    {
      "action_name": "auto-set_default_settings",
      "description": "将设备设置恢复为默认配置。",
      "description_en": "Restore the device settings to their default configuration."
    },
    {
      "action_name": "auto-set_manual_mode",
      "description": "将设备切换到手动操作模式。",
      "description_en": "Set the device to manual operation mode."
    },
    {
      "action_name": "auto-set_computer_mode",
      "description": "将设备切换到计算机控制模式。",
      "description_en": "Set the device to computer control mode."
    },
    {
      "action_name": "auto-flash_leds",
      "description": "闪烁设备指示灯。",
      "description_en": "Flash the device LEDs."
    },
    {
      "action_name": "auto-move_rel",
      "description": "使滚转轴按相对位移进行转动。",
      "description_en": "Move the roll axis by a relative amount."
    },
    {
      "action_name": "auto-move_abs",
      "description": "使滚转轴移动到指定绝对位置。",
      "description_en": "Move the roll axis to an absolute position."
    },
    {
      "action_name": "auto-get_device_mode_bit_status",
      "description": "获取设备模式位状态。",
      "description_en": "Get the status of the device mode bits."
    },
    {
      "action_name": "auto-turn_leds_off",
      "description": "关闭设备指示灯。",
      "description_en": "Turn off the device LEDs."
    },
    {
      "action_name": "auto-turn_leds_on",
      "description": "打开设备指示灯。",
      "description_en": "Turn on the device LEDs."
    },
    {
      "action_name": "auto-enable_motor_knob",
      "description": "启用电机旋钮手动控制。",
      "description_en": "Enable the motor knob for manual control."
    },
    {
      "action_name": "auto-disable_motor_knob",
      "description": "禁用电机旋钮手动控制。",
      "description_en": "Disable the motor knob for manual control."
    },
    {
      "action_name": "auto-enable_manual_move_reply",
      "description": "启用手动移动反馈。",
      "description_en": "Enable manual move reporting."
    },
    {
      "action_name": "auto-disable_manual_move_reply",
      "description": "禁用手动移动反馈。",
      "description_en": "Disable manual move reporting."
    },
    {
      "action_name": "auto-enable_circular_phase_microstepping",
      "description": "启用圆相位微步控制。",
      "description_en": "Enable circular phase microstepping."
    },
    {
      "action_name": "auto-disable_circular_phase_microstepping",
      "description": "禁用圆相位微步控制。",
      "description_en": "Disable circular phase microstepping."
    },
    {
      "action_name": "auto-enable_anti_backlash_routine",
      "description": "启用消隙例程。",
      "description_en": "Enable the anti-backlash routine."
    },
    {
      "action_name": "auto-disable_anti_backlash_routine",
      "description": "禁用消隙例程。",
      "description_en": "Disable the anti-backlash routine."
    },
    {
      "action_name": "auto-enable_anti_sticktion_routine",
      "description": "启用防静摩擦例程。",
      "description_en": "Enable the anti-stiction routine."
    },
    {
      "action_name": "auto-disable_anti_sticktion_routine",
      "description": "禁用防静摩擦例程。",
      "description_en": "Disable the anti-stiction routine."
    },
    {
      "action_name": "auto-enable_move_tracking",
      "description": "启用运动跟踪功能。",
      "description_en": "Enable move tracking."
    },
    {
      "action_name": "auto-disable_move_tracking",
      "description": "禁用运动跟踪功能。",
      "description_en": "Disable move tracking."
    },
    {
      "action_name": "auto-get_speed",
      "description": "获取运动速度。",
      "description_en": "Get the motion speed."
    },
    {
      "action_name": "auto-set_speed",
      "description": "设置运动速度。",
      "description_en": "Set the motion speed."
    },
    {
      "action_name": "auto-get_acceleration",
      "description": "获取运动加速度。",
      "description_en": "Get the acceleration."
    },
    {
      "action_name": "auto-set_acceleration",
      "description": "设置运动加速度。",
      "description_en": "Set the acceleration."
    },
    {
      "action_name": "auto-get_microstep_resolution",
      "description": "获取微步分辨率。",
      "description_en": "Get the microstep resolution."
    },
    {
      "action_name": "auto-set_microstep_resolution",
      "description": "设置微步分辨率。",
      "description_en": "Set the microstep resolution."
    },
    {
      "action_name": "auto-nm_per_step",
      "description": "获取每步对应的纳米位移标定值。",
      "description_en": "Get the calibrated nanometers-per-step value."
    }
  ]
}

